const status=document.getElementById('lab-control-status');
async function call(operation,body={}){const r=await fetch('/lab-api',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation,...body})}),data=await r.json();if(!r.ok)throw Error(data.error);return data;}
const run=async f=>{try{await f();}catch(e){status.textContent=e.message;}};
document.getElementById('lab-scenario').addEventListener('change',e=>run(async()=>{await call('labScenario',{scenario:e.target.value});status.textContent='Cenário aplicado ao próximo envio simulado.';}));
document.getElementById('lab-resolve').addEventListener('click',()=>run(async()=>{await call('labResolve');status.textContent='Consulta liberada. Clique em Verificar entrega no pedido.';}));
async function buyer(){const d=await call('labBuyer'),root=document.getElementById('lab-buyer-orders');root.replaceChildren();const p=document.createElement('p');p.textContent=`Saldo fictício: ${d.wallet.balance} CFF COINS`;root.append(p);for(const o of d.gameOrders.entries){const row=document.createElement('p');row.textContent=`${o.title} · ${o.id.slice(0,8)} · ${o.status} · ${o.delivery?.state||'sem envio'}`;if(o.status==='pending'){const b=document.createElement('button');b.textContent='Cancelar como comprador';b.className='cff-account-button';b.onclick=()=>run(async()=>{await call('labCancel',{orderId:o.id});await buyer();status.textContent='Pedido cancelado e CFF COINS fictícios estornados.';});row.append(b);}root.append(row);}}
document.getElementById('lab-buyer').addEventListener('click',()=>run(buyer));
